"""benchy_enclosure — generated by `calipers generate enclosure`; every dimension is sourced."""
from build123d import *

PARAMS = {
    'ref_min_x': (-29.176, 'measured:benchy.bbox_min.x'),
    'ref_max_x': (30.825, 'measured:benchy.bbox_max.x'),
    'ref_min_y': (-15.502, 'measured:benchy.bbox_min.y'),
    'ref_max_y': (15.502, 'measured:benchy.bbox_max.y'),
    'ref_min_z': (0.0, 'measured:benchy.bbox_min.z'),
    'ref_max_z': (48.0, 'measured:benchy.bbox_max.z'),
    'clearance': (0.6, 'spec:fit.0.min'),
    'wall':      (2.0, 'derived:printability.min_wall + 0.05 (spec margin)'),
    'floor':     (2.0, 'derived:wall'),
    'corner_r':  (4.0, 'assumption:outer corner radius (generator option)'),
}
P = {k: v[0] for k, v in PARAMS.items()}

def box_between(lo, hi):
    size = [hi[i] - lo[i] for i in range(3)]
    center = [(lo[i] + hi[i]) / 2 for i in range(3)]
    return Pos(*center) * Box(*size)

# cavity: the reference envelope grown by the clearance on every side
cav_lo = [P["ref_min_x"] - P["clearance"], P["ref_min_y"] - P["clearance"], P["ref_min_z"] - P["clearance"]]
cav_hi = [P["ref_max_x"] + P["clearance"], P["ref_max_y"] + P["clearance"], P["ref_max_z"] + P["clearance"]]
# outer shell: walls around the cavity, a floor opposite the open face (+z), nothing on it
out_lo = [cav_lo[0] - P["wall"], cav_lo[1] - P["wall"], cav_lo[2] - P["floor"]]
out_hi = [cav_hi[0] + P["wall"], cav_hi[1] + P["wall"], cav_hi[2]]
outer = box_between(out_lo, out_hi)
outer = fillet(outer.edges().filter_by(Axis.Z), radius=P["corner_r"])
# the open side: run the cavity out through the shell so that face is open
cav_hi[2] = cav_hi[2] + P["wall"]
cavity = box_between(cav_lo, cav_hi)
result = outer - cavity
